import pytest


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits (0 <= k <= 7).

    The high k bits wrap around to the low end. The result is in 0..255.
    """
    if not 0 <= x <= 255:
        raise ValueError(f"x out of range: {x}")
    if not 0 <= k <= 7:
        raise ValueError(f"k out of range: {k}")
    return ((x << k) | (x >> (8 - k))) & 0xFF


def test_rotl8_zero_shift() -> None:
    assert rotl8(0b10110001, 0) == 0b10110001
    assert rotl8(0, 0) == 0
    assert rotl8(255, 0) == 255


def test_rotl8_basic() -> None:
    assert rotl8(0b00000001, 1) == 0b00000010
    assert rotl8(0b00000001, 7) == 0b10000000
    assert rotl8(0b00001111, 4) == 0b11110000


def test_rotl8_wraps_high_bits() -> None:
    assert rotl8(0b10000000, 1) == 0b00000001
    assert rotl8(0b10110001, 1) == 0b01100011
    assert rotl8(0b11000000, 2) == 0b00000011
    assert rotl8(0b10110001, 3) == 0b10001101


def test_rotl8_all_zeros_and_ones() -> None:
    for k in range(8):
        assert rotl8(0, k) == 0
        assert rotl8(255, k) == 255


def test_rotl8_result_in_range() -> None:
    for x in range(256):
        for k in range(8):
            assert 0 <= rotl8(x, k) <= 255


def test_rotl8_popcount_preserved() -> None:
    for x in range(256):
        for k in range(8):
            assert bin(rotl8(x, k)).count("1") == bin(x).count("1")


def test_rotl8_inverse_by_complement() -> None:
    for x in range(256):
        for k in range(1, 8):
            assert rotl8(rotl8(x, k), 8 - k) == x


def test_rotl8_composition() -> None:
    for x in range(256):
        for a in range(8):
            for b in range(8):
                assert rotl8(rotl8(x, a), b) == rotl8(x, (a + b) % 8)


def test_rotl8_matches_reference() -> None:
    for x in range(256):
        for k in range(8):
            expected = ((x << k) | (x >> (8 - k))) & 0xFF
            assert rotl8(x, k) == expected


def test_rotl8_rejects_out_of_range() -> None:
    with pytest.raises(ValueError):
        rotl8(256, 1)
    with pytest.raises(ValueError):
        rotl8(-1, 1)
    with pytest.raises(ValueError):
        rotl8(1, 8)
    with pytest.raises(ValueError):
        rotl8(1, -1)

